       "text": "I originally wanted to analyze the impact of the war on industries on both sides. But there really isn’t much to talk about. Anyway, in summary, this is The military industry sucked away capital and labor, and civilian industry was squeezed out on a large scale. But there is one bright spot, which is also a star industry that is rising rapidly on both sides. It can even be said that an industry that grew out of thin air is drones. Now everyone should be aware of the role of drones in contemporary warfare, right? It is estimated that the number of casualties it caused accounted for about 2/3 of the total number of Russian-Ukrainian wars. It can be said that both sides have made nationwide efforts to develop the drone industry in the past two years. For example, there is a star model of suicide drone in Russia called \"Shahed\" \"Shahed\" When you hear the name Shaheed, do you hear it?"
