       "text": "Turning an almost non-existent industry into the world's most successful drone empire Also started to sell reversely to the whole world Pre-war Ukrainian drone production was approximately 3,000 a year The development of this industry is expected to reach 10 million in 2026 We won’t go into details, but I think one of the interesting things inside is that there are so many drones. How does it decide how to allocate it to various units? The Ukrainian government It directly launched an online shopping platform called Brave1 Its official definition says that Brave1 is a network connected to the Ukrainian military and developers of online platforms for various defense forces You can place an order to buy a drone on this platform. What can you buy?"
