       "text": "Robotic electronics and whatnot but mainly drones And what do these troops spend to place orders? It’s not money, it’s reliance War points roughly mean that each combat unit will be based on performance Get a war point. The better you perform, the higher the points. The higher the points. You can go to the Brave1 platform and buy more drones so you can jump over a lot Cumbersome processes within the force also help military supplies This battle is fought by allocating good guys based on market supply and demand. It’s all made the Internet innovate me. These are the interesting ways that Russia and Ukraine have chosen to play around the military industry and drones. I also want to try my best to avoid subjective evaluation, just through these examples."
