       "text": "In fact, you see, both sides of this war are fighting with borrowed capital. Russia is borrowing from its increasingly bottoming out reserves, while Ukraine is borrowing I am borrowing aid from the West that may be cut off at any time. On the one hand, there are internal injuries caused by the expansion of military industry and the shrinking of people's livelihood. On one side is the outer suspension that stops immediately as soon as the assistance is stopped. I actually hope everyone can feel my purpose in making this video It’s not about comparing who loses and who wins. But it allows everyone to see the cost of war more clearly. No matter how this account is calculated, the final conclusion will always be the same economic wound. It may recover slowly but at some cost"
